<?php require 'header.php';$rows=$pdo->query('SELECT p.sku,p.product_name,p.unit,w.warehouse_name,l.bin_code,s.qty_on_hand,s.qty_reserved,(s.qty_on_hand-s.qty_reserved) available,p.minimum_stock FROM stock_balances s JOIN products p ON p.product_id=s.product_id JOIN storage_locations l ON l.location_id=s.location_id JOIN warehouses w ON w.warehouse_id=l.warehouse_id ORDER BY p.product_name,l.bin_code')->fetchAll();$low=0;foreach($rows as $r)if($r['available']<=$r['minimum_stock'])$low++;?><div class="page-intro"><div><h2>Laporan stok</h2><p>Posisi stok terkini berdasarkan lokasi penyimpanan.</p></div><button class="outline" onclick="window.print()">⎙ Cetak laporan</button></div><div class="report-bar"><div><span>Total catatan stok</span><b><?=count($rows)?></b></div><div><span>Perlu reorder</span><b class="warning-text"><?=$low?></b></div><div><span>Stok aman</span><b class="success-text"><?=count($rows)-$low?></b></div></div><section class="panel"><div class="panel-head"><div><h3>Detail stok per lokasi</h3><p>Warna status menunjukkan prioritas pengadaan material.</p></div><div class="legend"><span><i class="dot green-dot"></i>Aman</span><span><i class="dot red-dot"></i>Reorder</span></div></div><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Lokasi</th><th>Fisik</th><th>Dialokasikan</th><th>Tersedia</th><th>Minimum</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):$isLow=$r['available']<=$r['minimum_stock'];?><tr><td><code><?=e($r['sku'])?></code><br><b><?=e($r['product_name'])?></b></td><td><?=e($r['warehouse_name'])?><small><?=e($r['bin_code'])?></small></td><td><?=e($r['qty_on_hand'].' '.$r['unit'])?></td><td><?=e($r['qty_reserved'].' '.$r['unit'])?></td><td><b><?=e($r['available'].' '.$r['unit'])?></b></td><td><?=e($r['minimum_stock'].' '.$r['unit'])?></td><td><span class="badge <?=$isLow?'danger':'safe'?>"><?=$isLow?'Reorder':'Aman'?></span></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">Belum ada data stok. Input transaksi barang masuk terlebih dahulu.</td></tr><?php endif?></tbody></table></div></section><?php require 'footer.php';?>